# Alternative names clients may send for an existing design.
STYLE_ALIASES = {
    'minimal': 'modern',
}

DEFAULT_STYLE = 'classic'


def get_style_template(style: str) -> str:
    """Return the reference template for a style, falling back to classic."""
    style = STYLE_ALIASES.get(style, style)
    return CV_TEMPLATES.get(style, CV_TEMPLATES[DEFAULT_STYLE])


def get_style_reference(style: str) -> str:
    """Return just the CSS for a style, for use as the prompt's style reference.

    The full template carries a dummy CV ("JOHN SMITH" and friends) which the
    prompt then has to spend instructions telling the model to ignore. The CSS
    alone conveys the design and keeps the class names the model needs, at about
    a third of the size.
    """
    template = get_style_template(style)
    start = template.find('<style>')
    end = template.find('</style>', start)
    if start == -1 or end == -1:
        return template  # unexpected shape; fall back to the whole thing
    return template[start + len('<style>'):end].strip()


def get_style_class_names(style: str) -> list:
    """Class names used by a style's CSS, so generated HTML can match it."""
    css = get_style_reference(style)
    names = re.findall(r'\.([a-zA-Z][\w-]*)', css)
    seen = []
    for name in names:
        if name not in seen:
            seen.append(name)
    return seen
